      } else {
        this.activeTab = 'intro';
      }
    }
  },
  methods: {
    handleSelect(key) {
      this.activeTab = key;

      // 修复路由导航错误
      const currentQuery = this.$route.query.tab;
      try {
        if (key === 'intro') {
          if (currentQuery) {
            // 只有当需要移除查询参数时才导航
            this.$router.push({
              path: '/school-overview',
              query: {}
            }).catch(err => {
              if (err.name !== 'NavigationDuplicated') {
                throw err;
              }
            });
          }
        } else if (key !== currentQuery) {
          // 只有当切换到不同的标签页时才导航
          this.$router.push({
            path: '/school-overview',
            query: {
              tab: key
            }
          }).catch(err => {
            if (err.name !== 'NavigationDuplicated') {
              throw err;
            }
          });
        }
      } catch (err) {
        // 忽略导航重复错误
